INSERT OR IGNORE INTO content_blocks (id, section_key, title, content_markdown, content_type) VALUES
  (lower(hex(randomblob(8))), 'seo-homepage', 'SEO – Homepage', '{"title":"Bicom Písek | Biorezonanční poradna Písek","description":"Biorezonanční metoda Bicom Optima v Písku. Šetrná, certifikovaná a neinvazivní komplementární podpora pro děti i dospělé. Objednejte se online.","ogTitle":"Bicom Písek | Biorezonance","ogDescription":"Šetrná certifikovaná komplementární péče s respektem k vašemu příběhu. Zkuste bezbolestnou biorezonanci Bicom Optima v Písku.","ogImage":"https://bicom-pisek.cz/assets/img/og.jpg","canonical":"https://bicom-pisek.cz/"}', 'config'),
  (lower(hex(randomblob(8))), 'seo-pisek', 'SEO – Písek', '{"title":"Biorezonance Písek | Bicom Optima — šetrná komplementární péče","description":"Biorezonance Bicom Optima pro klienty z Písku. Šetrná, neinvazivní a certifikovaná komplementární podpora organismu. přímo v naší ordinaci. Objednejte se online.","ogTitle":"Biorezonance Písek | Bicom Písek","ogDescription":"Šetrná certifikovaná komplementární biorezonance Bicom Optima pro klienty z Písku.","ogImage":"https://bicom-pisek.cz/assets/img/og.jpg","canonical":"https://bicom-pisek.cz/biorezonance-pisek.html"}', 'config'),
  (lower(hex(randomblob(8))), 'seo-strakonice', 'SEO – Strakonice', '{"title":"Biorezonance Strakonice | Bicom Optima — šetrná komplementární péče","description":"Biorezonance Bicom Optima pro klienty ze Strakonic. Šetrná, neinvazivní a certifikovaná komplementární podpora organismu. cca 20 minut autem do Písku. Objednejte se online.","ogTitle":"Biorezonance Strakonice | Bicom Písek","ogDescription":"Šetrná certifikovaná komplementární biorezonance Bicom Optima pro klienty ze Strakonic.","ogImage":"https://bicom-pisek.cz/assets/img/og.jpg","canonical":"https://bicom-pisek.cz/biorezonance-strakonice.html"}', 'config'),
  (lower(hex(randomblob(8))), 'seo-vodnany', 'SEO – Vodňany', '{"title":"Biorezonance Vodňany | Bicom Optima — šetrná komplementární péče","description":"Biorezonance Bicom Optima pro klienty z Vodňan. Šetrná, neinvazivní a certifikovaná komplementární podpora organismu. cca 20 minut autem do Písku. Objednejte se online.","ogTitle":"Biorezonance Vodňany | Bicom Písek","ogDescription":"Šetrná certifikovaná komplementární biorezonance Bicom Optima pro klienty z Vodňan.","ogImage":"https://bicom-pisek.cz/assets/img/og.jpg","canonical":"https://bicom-pisek.cz/biorezonance-vodnany.html"}', 'config'),
  (lower(hex(randomblob(8))), 'seo-milevsko', 'SEO – Milevsko', '{"title":"Biorezonance Milevsko | Bicom Optima — šetrná komplementární péče","description":"Biorezonance Bicom Optima pro klienty z Milevska. Šetrná, neinvazivní a certifikovaná komplementární podpora organismu. cca 25 minut autem do Písku. Objednejte se online.","ogTitle":"Biorezonance Milevsko | Bicom Písek","ogDescription":"Šetrná certifikovaná komplementární biorezonance Bicom Optima pro klienty z Milevska.","ogImage":"https://bicom-pisek.cz/assets/img/og.jpg","canonical":"https://bicom-pisek.cz/biorezonance-milevsko.html"}', 'config'),
  (lower(hex(randomblob(8))), 'seo-protivin', 'SEO – Protivín', '{"title":"Biorezonance Protivín | Bicom Optima — šetrná komplementární péče","description":"Biorezonance Bicom Optima pro klienty z Protivína. Šetrná, neinvazivní a certifikovaná komplementární podpora organismu. cca 12 minut autem do Písku. Objednejte se online.","ogTitle":"Biorezonance Protivín | Bicom Písek","ogDescription":"Šetrná certifikovaná komplementární biorezonance Bicom Optima pro klienty z Protivína.","ogImage":"https://bicom-pisek.cz/assets/img/og.jpg","canonical":"https://bicom-pisek.cz/biorezonance-protivin.html"}', 'config'),
  (lower(hex(randomblob(8))), 'faq-main', 'FAQ (sdílené)', '[{"q":"Často mě bolí hlava nebo mívám migrény. Co s tím?","a":"Opakované bolesti hlavy a migrény bývají spojené s napětím, stresem i zátěží organismu. Biorezonanční metoda Bicom může podpořit přirozené regenerační procesy a zmírnit napětí — jako šetrný doplněk, ne náhrada lékařské péče. Vhodný program: <a href=#bolest-a-pohybovy-aparat>Bolest a pohybový aparát</a>."},{"q":"Mám problémy usnout a špatně se mi spí. Co na to pomáhá?","a":"Nekvalitní spánek často souvisí s dlouhodobým stresem a nerovnováhou nervové soustavy. Metoda Bicom podporuje zklidnění a emoční rovnováhu; mnozí klienti popisují větší klid. Podívejte se na program <a href=#psychika-a-emocni-rovnovaha>Psychika a emoční rovnováha</a>."},{"q":"Jsem pořád unavený, i když se vyspím. Dá se s tím něco dělat?","a":"Dlouhodobá únava, která nepřejde ani po odpočinku, může mít mnoho příčin — nejprve je dobré vyloučit lékařské. Biorezonance Bicom se používá jako podpora obnovy energie a regenerace. Vhodný je program <a href=#energie-a-vitalita>Energie &amp; Vitalita</a>."},{"q":"Dítě má alergie a pořád je nemocné. Můžete pomoci?","a":"U opakovaných infekcí a alergií volí rodiče šetrný, neinvazivní přístup. Metoda Bicom je bezbolestná a vhodná i pro děti (se souhlasem zákonného zástupce, jako doplněk pediatrické péče). Viz <a href=#imunita-a-obranyschopnost>Imunita a obranyschopnost</a>."},{"q":"Chci přestat kouřit, ale nedaří se mi to. Pomůže biorezonance?","a":"Odvykání je hlavně o motivaci a návyku. Biorezonance Bicom se používá jako podpora při snižování nutkání — obvykle jedním delším sezením. Není to garance, funguje nejlépe jako součást rozhodnutí. Více v programu <a href=#psychika-a-emocni-rovnovaha>Psychika a emoční rovnováha</a>."},{"q":"Trápí mě nafouklé břicho a trávení po antibiotikách. Co s tím?","a":"Po antibiotikách bývá narušená rovnováha trávení a mikrobiomu. Metoda Bicom může podpořit přirozenou detoxikaci a rovnováhu — vždy spolu s rozumnou stravou. Vhodný program: <a href=#organy-a-detoxikace>Orgány a detoxikace</a>."}]', 'config'),
  (lower(hex(randomblob(8))), 'landing-pisek', 'Landing – Písek', '{"tagline":"Biorezonance pro Písek a okolí","h1City":"Písek","heroDesc":"Hledáte šetrnou, neinvazivní podporu organismu v okolí Písku? Biorezonanční metoda Bicom Optima v Písku je dostupná i pro vás — přímo v naší ordinaci. Citlivě, bez chemie a s respektem k vašemu příběhu.","availTitle":"Biorezonance dostupná z Písku","availIntro":"Ordinace Bicom Písek sídlí přímo v Písku (Vladislavova 201 (technologický park)). Jste-li z Písku a okolí, máte to k nám jen pár minut.","faqTitle":"Časté otázky lidí z Písku","ctaIntro":"Jste z Písku nebo okolí? Rezervujte si termín online. Po odeslání vás kontaktujeme pro potvrzení přesného času.","footerBrandDesc":"Šetrná podpora rovnováhy organismu certifikovanou biorezonanční metodou Bicom Optima. Dostupná i pro klienty z Písku."}', 'config'),
  (lower(hex(randomblob(8))), 'landing-strakonice', 'Landing – Strakonice', '{"tagline":"Biorezonance pro Strakonice a okolí","h1City":"Strakonice","heroDesc":"Hledáte šetrnou, neinvazivní podporu organismu v okolí Strakonic? Biorezonanční metoda Bicom Optima v Písku je dostupná i pro vás — cca 20 minut autem do Písku. Citlivě, bez chemie a s respektem k vašemu příběhu.","availTitle":"Biorezonance dostupná ze Strakonic","availIntro":"Ze Strakonic je to do naší písecké ordinace přibližně 20 minut po silnici I/4. Mnoho našich klientů dojíždí právě ze Strakonicka — rádi vám termín přizpůsobíme.","faqTitle":"Časté otázky lidí ze Strakonic","ctaIntro":"Jste ze Strakonic nebo okolí? Rezervujte si termín online. Po odeslání vás kontaktujeme pro potvrzení přesného času.","footerBrandDesc":"Šetrná podpora rovnováhy organismu certifikovanou biorezonanční metodou Bicom Optima. Dostupná i pro klienty ze Strakonic."}', 'config'),
  (lower(hex(randomblob(8))), 'landing-vodnany', 'Landing – Vodňany', '{"tagline":"Biorezonance pro Vodňany a okolí","h1City":"Vodňany","heroDesc":"Hledáte šetrnou, neinvazivní podporu organismu v okolí Vodňan? Biorezonanční metoda Bicom Optima v Písku je dostupná i pro vás — cca 20 minut autem do Písku. Citlivě, bez chemie a s respektem k vašemu příběhu.","availTitle":"Biorezonance dostupná z Vodňan","availIntro":"Z Vodňan dojedete do Písku zhruba za 20 minut. Pro klienty z Vodňanska je biorezonance Bicom dostupná blízká volba bez dlouhého cestování.","faqTitle":"Časté otázky lidí z Vodňan","ctaIntro":"Jste z Vodňan nebo okolí? Rezervujte si termín online. Po odeslání vás kontaktujeme pro potvrzení přesného času.","footerBrandDesc":"Šetrná podpora rovnováhy organismu certifikovanou biorezonanční metodou Bicom Optima. Dostupná i pro klienty z Vodňan."}', 'config'),
  (lower(hex(randomblob(8))), 'landing-milevsko', 'Landing – Milevsko', '{"tagline":"Biorezonance pro Milevsko a okolí","h1City":"Milevsko","heroDesc":"Hledáte šetrnou, neinvazivní podporu organismu v okolí Milevska? Biorezonanční metoda Bicom Optima v Písku je dostupná i pro vás — cca 25 minut autem do Písku. Citlivě, bez chemie a s respektem k vašemu příběhu.","availTitle":"Biorezonance dostupná z Milevska","availIntro":"Z Milevska je to do naší ordinace v Písku okolo 25 minut. Klientům z Milevska a okolních obcí nabízíme klidné, nespěchané konzultace.","faqTitle":"Časté otázky lidí z Milevska","ctaIntro":"Jste z Milevska nebo okolí? Rezervujte si termín online. Po odeslání vás kontaktujeme pro potvrzení přesného času.","footerBrandDesc":"Šetrná podpora rovnováhy organismu certifikovanou biorezonanční metodou Bicom Optima. Dostupná i pro klienty z Milevska."}', 'config'),
  (lower(hex(randomblob(8))), 'landing-protivin', 'Landing – Protivín', '{"tagline":"Biorezonance pro Protivín a okolí","h1City":"Protivín","heroDesc":"Hledáte šetrnou, neinvazivní podporu organismu v okolí Protivína? Biorezonanční metoda Bicom Optima v Písku je dostupná i pro vás — cca 12 minut autem do Písku. Citlivě, bez chemie a s respektem k vašemu příběhu.","availTitle":"Biorezonance dostupná z Protivína","availIntro":"Protivín je Písku nejblíž — dojezd je jen okolo 12 minut. Pro klienty z Protivínska je naše poradna prakticky za rohem.","faqTitle":"Časté otázky lidí z Protivína","ctaIntro":"Jste z Protivína nebo okolí? Rezervujte si termín online. Po odeslání vás kontaktujeme pro potvrzení přesného času.","footerBrandDesc":"Šetrná podpora rovnováhy organismu certifikovanou biorezonanční metodou Bicom Optima. Dostupná i pro klienty z Protivína."}', 'config');
